print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{out}'")

    # Let's examine character by character
    for j in range(max(len(inp), len(out))):
        in_char = inp[j] if j < len(inp) else None
        out_char = out[j] if j < len(out) else None

        if in_char != out_char:
            print(f"  Position {j}: '{in_char}' -> '{out_char}'")

    # Special cases
    if len(inp) > len(out):
        print(f"  Removed {len(inp) - len(out)} characters")
    elif len(out) > len(inp):
        print(f"  Added {len(out) - len(inp)} characters")

